import React, {useState} from 'react';

function Square(props) {
    return (
        <button className='square' onClick={props.onClick}>
            {props.value}
        </button>
    );
}

function clickHandler(i) {
    const nextSquares = squares.slice();
    nextSquares[i] = 'O';
    setSquares(nextSquares);
}

export default function Board() {
    const [squares, setSquares] = useState(Array(9).fill(null));

    return (
        <>
            <div className='board-row'>
                <Square
                    value='X'
                    onClick={() => {
                        clickHandler(0);
                    }}
                />
                <Square
                    value='X'
                    onClick={() => {
                        clickHandler(1);
                    }}
                />
                <Square
                    value='X'
                    onClick={() => {
                        clickHandler(2);
                    }}
                />
            </div>
            <div className='board-row'>
                <Square
                    value='X'
                    onClick={() => {
                        clickHandler(3);
                    }}
                />
                <Square
                    value='X'
                    onClick={() => {
                        clickHandler(4);
                    }}
                />
                <Square
                    value='X'
                    onClick={() => {
                        clickHandler(5);
                    }}
                />
            </div>
            <div className='board-row'>
                <Square
                    value='X'
                    onClick={() => {
                        clickHandler(6);
                    }}
                />
                <Square
                    value='Y'
                    onClick={() => {
                        clickHandler(7);
                    }}
                />
                <Square
                    value='X'
                    onClick={() => {
                        clickHandler(8);
                    }}
                />
            </div>
        </>
    );
}
